import{_ as t,o as a,c as n,a6 as r}from"./chunks/framework.CCKCzdWs.js";const s="/screenshots/credentials-settings.png",u=JSON.parse('{"title":"Credentials","description":"Save a secret Piwi sends to a CI server, a Git host, an AI provider, Jira, Zephyr Scale or Slack once, bind it to the address it may reach, and read the log of every use.","frontmatter":{"title":"Credentials","description":"Save a secret Piwi sends to a CI server, a Git host, an AI provider, Jira, Zephyr Scale or Slack once, bind it to the address it may reach, and read the log of every use.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/operate/credentials.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/operate/credentials.html"}],["meta",{"property":"og:title","content":"Credentials | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Save a secret Piwi sends to a CI server, a Git host, an AI provider, Jira, Zephyr Scale or Slack once, bind it to the address it may reach, and read the log of every use."}]]},"headers":[],"relativePath":"operate/credentials.md","filePath":"operate/credentials.md","lastUpdated":1795254567000}'),o={name:"operate/credentials.md"};function i(d,e,c,h,l,g){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="credentials" tabindex="-1">Credentials <a class="header-anchor" href="#credentials" aria-label="Permalink to &quot;Credentials&quot;">​</a></h1><p>A credential is a secret Piwi sends to another service, saved once under <strong>Settings → Credentials</strong> and named wherever it is needed: a CI server action, <a href="/guide/source-control.html">source control</a>, an AI role, a Jira or Zephyr Scale connection or a Slack channel. A rotation is one change, and every use is logged.</p><figure><img src="'+s+'" alt="Settings → Credentials: two Jenkins and two GitHub credentials, a Jenkins one open in a panel with its user, destination, projects, the three CI actions that name it and its log of dispatches and checks"><figcaption>Settings → Credentials: a credential&#39;s panel, with the CI actions that name it and its log.</figcaption></figure><h2 id="what-a-credential-holds" tabindex="-1">What a credential holds <a class="header-anchor" href="#what-a-credential-holds" aria-label="Permalink to &quot;What a credential holds&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>What it is</th></tr></thead><tbody><tr><td><strong>Service</strong></td><td><strong>CI server</strong>, <strong>Source control</strong> for a GitHub, GitLab or Bitbucket token, <strong>AI provider</strong>, <strong>Jira Cloud</strong>, <strong>Zephyr Scale</strong> or <strong>Slack</strong>.</td></tr><tr><td><strong>Name</strong></td><td>Unique on the instance, ignoring case; the name the pickers and the log show.</td></tr><tr><td><strong>Destination</strong></td><td>The base URL the secret may be sent under (<code>https://jenkins.example.com/</code>). A request to any other address, or outside its path, is refused.</td></tr><tr><td><strong>User</strong></td><td>The user name sent with the secret as HTTP Basic authentication, when a CI server takes one; for Jira, the account&#39;s e-mail.</td></tr><tr><td><strong>Secret</strong></td><td>The API token, saved encrypted with <code>PIWI_SECRET_KEY</code>, together with the destination, or read from a server variable (below). Never returned by any page, API answer or log.</td></tr><tr><td><strong>Projects</strong></td><td>The projects that may name it: a list, or all projects, present and future.</td></tr><tr><td><strong>Inputs</strong></td><td>For a CI server, the CI action inputs a request carrying it may send beside the arguments and the dispatch id: every input, or the names listed.</td></tr><tr><td><strong>Custom requests</strong></td><td>For a CI server, whether a Custom request may carry it. Off by default: a Custom request can reach any path under the destination, a CI server&#39;s script console included.</td></tr></tbody></table><p>Saving a secret needs <code>PIWI_SECRET_KEY</code> (see the <a href="./production-checklist.html">production checklist</a>); without it, the form says so and nothing is saved. Changing the destination asks for the secret again, since the secret is sealed with the one destination it may be sent under.</p><h2 id="a-secret-from-a-server-variable" tabindex="-1">A secret from a server variable <a class="header-anchor" href="#a-secret-from-a-server-variable" aria-label="Permalink to &quot;A secret from a server variable&quot;">​</a></h2><p>An administrator can have a credential read its secret from a variable of the server&#39;s environment instead of saving it: <strong>Secret source</strong> → <strong>Read from a server variable</strong>, then the variable&#39;s name. Only a variable named <code>PIWI_CREDENTIAL_…</code> (capitals, digits and <code>_</code>) can be named, so no other variable of the server, such as <code>PIWI_SECRET_KEY</code> or a database URL, can be sent anywhere. Set it as the server&#39;s other variables are set, from a secrets store or the container&#39;s environment:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_CREDENTIAL_JENKINS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">11a2b3c4d5e6f7a8b9c0d1e2f3a4b5c6</span></span></code></pre></div><p>The variable is read at each use, so changing it and restarting the server is the rotation. Its name is sealed with the destination like a saved secret, so a new destination is saved with the name again (the form sends it). The panel says when the variable is not set on the server, and a dispatch is then refused and logged. Only an administrator may change a credential that reads a variable.</p><h2 id="who-manages-them" tabindex="-1">Who manages them <a class="header-anchor" href="#who-manages-them" aria-label="Permalink to &quot;Who manages them&quot;">​</a></h2><p>An administrator (the <code>credentials:manage</code> permission) creates, changes, disables and deletes any credential, and is the only one who may share one with all projects. A Project admin opens <strong>Settings → Credentials</strong> too, and sees there the credentials they manage: the ones they created, shared only with projects they manage and reading no variable. They create them there or from a project&#39;s <strong>CI</strong> or <strong>Source control</strong> settings. A credential an administrator saved or changed is the administrator&#39;s: a Project admin picks it, and never loosens its rules or undoes a <strong>Disable</strong>. Anyone who manages a project picks any credential shared with it, for its CI actions or its source control, without ever reading its secret. See <a href="./project-access.html">Access, roles and groups</a>.</p><p><strong>Disable</strong> refuses every use of a credential at once, for an incident, without touching the actions that name it. <strong>Delete</strong> is refused while something names the credential (a CI action, source control, an AI role, a connection, a Slack channel): the answer lists them.</p><h2 id="using-one-in-a-ci-action" tabindex="-1">Using one in a CI action <a class="header-anchor" href="#using-one-in-a-ci-action" aria-label="Permalink to &quot;Using one in a CI action&quot;">​</a></h2><p>In <strong>Project → Settings → CI</strong>, a CI server action&#39;s editor has a <strong>Credential</strong> picker and a <strong>New credential</strong> button. The action&#39;s base URL may stay empty: it is then the credential&#39;s destination. The request preview shows which credential the request carries, and says when the credential would refuse it.</p><p>Each dispatch and each <strong>Check</strong> checks the credential again before anything is sent: still active, shared with the project, and holding the request&#39;s URL under its destination, and allowing a Custom request when the action sends one.</p><h2 id="what-names-a-credential" tabindex="-1">What names a credential <a class="header-anchor" href="#what-names-a-credential" aria-label="Permalink to &quot;What names a credential&quot;">​</a></h2><ul><li><strong>A CI action</strong>: a CI server action&#39;s requests, or the dispatch and the <strong>Check</strong> of a GitHub, GitLab or Bitbucket action (<a href="/features/ci-rerun.html">Re-run in CI</a>).</li><li><strong>Source control</strong>: a project&#39;s repository calls, else the instance&#39;s, with a GitHub, GitLab or Bitbucket token sent to the host&#39;s API (<a href="/guide/source-control.html#set-the-credential">Source control</a>).</li><li><strong>An AI role</strong>: the key of a role of <strong>Settings → AI</strong>, sent to its provider (<a href="/guide/ai-provider.html#api-keys">AI provider</a>).</li><li><strong>A Jira or Zephyr Scale connection, or a global Slack channel</strong>: its token (<a href="#connections-and-slack-channels">below</a>).</li></ul><p>Whatever names it, a credential is checked and logged as this page says; each page says what its feature sends and how the secrets saved before credentials existed were moved.</p><h2 id="the-ci-server-credential-of-the-environment" tabindex="-1">The CI server credential of the environment <a class="header-anchor" href="#the-ci-server-credential-of-the-environment" aria-label="Permalink to &quot;The CI server credential of the environment&quot;">​</a></h2><p>The operator can set one CI server credential through the environment: <code>PIWI_CI_SERVER_URL</code>, <code>PIWI_CI_SERVER_USER</code> and <code>PIWI_CI_SERVER_TOKEN</code>. It shows on the page as a read-only credential, shared with all projects, and is sent by a CI server action that names no credential, only with a preset&#39;s request under <code>PIWI_CI_SERVER_URL</code>, and with only the inputs <code>PIWI_CI_SERVER_ALLOWED_INPUTS</code> lists. Its uses are logged like any other. See the <a href="/reference/configuration.html">configuration reference</a>.</p><p>A CI server token stored on a project (<code>projects.ci_server_token</code>) is moved to a credential at startup: bound to the URL it was saved with, shared with its project, allowed with a Custom request and every input, and named by the CI server actions it served. Two projects holding the same token for the same URL and user share one credential. An administrator manages it, since the database does not say who saved the token. A token that cannot be opened (a changed <code>PIWI_SECRET_KEY</code>) stays where it is, with a warning in the log at each start.</p><h2 id="connections-and-slack-channels" tabindex="-1">Connections and Slack channels <a class="header-anchor" href="#connections-and-slack-channels" aria-label="Permalink to &quot;Connections and Slack channels&quot;">​</a></h2><p>The token typed for a Jira or Zephyr Scale connection (<strong>Settings → Integrations</strong>) or a global Slack channel&#39;s bot (<strong>Settings → Notifications</strong>) becomes its credential, named after it, shared with all projects and sent only under the Jira site (a scoped token&#39;s Atlassian gateway counts as the site), the Zephyr Scale region&#39;s API or Slack&#39;s Web API. <strong>Saved credential</strong> picks another. A token typed later rotates the connection&#39;s credential, or saves a new one while something else names it. Opening a connection is a counted read; each write (an issue, a comment, a transition, an attachment, a results upload, a link) and each Slack message is a row. A personal channel keeps its own token. Deleting one asks whether to delete its credential too.</p><p><code>PIWI_JIRA_*</code> and <code>PIWI_ZEPHYR_*</code> make a read-only credential that reads the token from the variable. At startup, each connection&#39;s token moves to a credential of its own, and equal tokens of global channels to one.</p><h2 id="the-log" tabindex="-1">The log <a class="header-anchor" href="#the-log" aria-label="Permalink to &quot;The log&quot;">​</a></h2><p>A credential&#39;s panel lists its uses, newest first, and the page&#39;s <strong>Log</strong>, for an administrator, those of every credential, a deleted one and the environment&#39;s included:</p><ul><li><strong>What</strong>: a CI dispatch or a Check, with the CI action it was for; a repository read, a commit status, a pull-request comment or an auto-heal write, with its commit, pull request or branch; an AI model call; a read or a write of a Jira or Zephyr Scale connection; a Slack message, with its channel.</li><li><strong>Where</strong>: the project, and the request&#39;s origin and path (never its query).</li><li><strong>Who</strong>: the user who started it, and the API key when it came through one (an MCP tool, a script); for counted Checks, the last of the hour.</li><li><strong>How it ended</strong>: <code>sent</code> until the service answers, then <code>ok</code> or <code>failed</code> with the reason; <code>refused</code> when the credential&#39;s rules stopped it before anything was sent, with the reason.</li></ul><p>A dispatch or another write is one row. A Check or a repository read only reads, so the reads of a project are counted in one row per result and hour. The secret is masked in any reason a service&#39;s answer holds. The log is kept 365 days, or <code>PIWI_RETENTION_CREDENTIAL_LOG_DAYS</code> (0 keeps it forever), by the nightly sweep; a deleted credential&#39;s rows stay in the page&#39;s <strong>Log</strong>, under its name, until then.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/ci-rerun.html">Re-run in CI</a>: the CI actions that name a credential</li><li><a href="/guide/source-control.html">Source control</a>: what reads and writes a repository with an SCM credential</li><li><a href="./integrations.html">Jira Cloud</a> and <a href="./zephyr-scale.html">Zephyr Scale</a>: the connections that name a credential</li><li><a href="./project-access.html">Access, roles and groups</a>: who holds <code>credentials:manage</code> and <code>project:manage</code></li><li><a href="./production-checklist.html">Production checklist</a>: <code>PIWI_SECRET_KEY</code>, which encrypts every secret</li></ul>',31)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
